/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const job = id => ({ id, priority: Number(id) });
assert.equal(readLimit(), 3);
assert.equal(readLimit('0'), 3);
const pausedSaves = [];
const submitResult = await submit([job('1')], async j => { pausedSaves.push(j.id); });
assert.deepEqual(pausedSaves, ['1']);
console.log(JSON.stringify({probe:'pause', requested:0, actualLimit:readLimit('0'), pausedSaves, submitResult}));
const starts = [], finishes = [], releases = [];
await runQueue([job('1'), job('2')], '2', async j => {
  starts.push(j.id);
  await new Promise(resolve => releases.push(resolve));
  finishes.push(j.id);
});
assert.deepEqual(starts, ['1','2']);
assert.deepEqual(finishes, []);
console.log(JSON.stringify({probe:'sequential-and-awaited', startsAtQueueResolution:starts, finishesAtQueueResolution:finishes}));
releases.forEach(resolve => resolve());
await new Promise(resolve => setImmediate(resolve));
const failureStarts = [];
const failure = new Error('save failed');
const unhandled = new Promise(resolve => process.once('unhandledRejection', resolve));
let queueRejected = false;
try {
  await runQueue([job('1'), job('2')], '2', async j => {
    failureStarts.push(j.id);
    if (j.id === '1') throw failure;
  });
} catch { queueRejected = true; }
assert.equal(await unhandled, failure);
assert.equal(queueRejected, false);
assert.deepEqual(failureStarts, ['1','2']);
console.log(JSON.stringify({probe:'failure', queueRejected, failureStarts, unhandledRejection:'save failed'}));
const owned = [job('3'), job('1'), job('2')];
const before = owned.map(j => j.id);
await runQueue(owned, '1', async () => {});
assert.deepEqual(owned.map(j => j.id), ['1','2','3']);
console.log(JSON.stringify({probe:'ownership', before, after:owned.map(j => j.id)}));
NODE"

